app.get('/api/reports/cash.csv',allow('admin','owner','finance','auditor'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const r=await pool.query('SELECT occurred_at,movement_type,category,description,responsible,amount_cents,payment_method FROM cash_movements WHERE unit_id=$1 ORDER BY occurred_at',[u.id]);const csv=['data;tipo;categoria;descricao;responsavel;valor_centavos;forma_pagamento',...r.rows.map(x=>[x.occurred_at,x.movement_type,x.category,x.description,x.responsible,x.amount_cents,x.payment_method].map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(';'))].join('\r\n');res.setHeader('Content-Type','text/csv; charset=utf-8');res.setHeader('Content-Disposition','attachment; filename="caixa.csv"');res.send('\ufeff'+csv);}catch(e){next(e);}});
