app.get('/api/reports/dre.csv',allow('admin','owner','finance','auditor'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const month=/^\d{4}-\d{2}$/.test(req.query.month||'')?req.query.month:localToday().slice(0,7),start=`${month}-01`,end=new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5,7)),0)).toISOString().slice(0,10);const r=await pool.query(`SELECT COALESCE(c.dre_group,'unclassified') grupo,COALESCE(sum(e.total_cents),0)::text valor_centavos,count(e.id)::int lancamentos FROM expenses e LEFT JOIN categories c ON c.id=e.category_id WHERE e.unit_id=$1 AND e.accrual_date BETWEEN $2 AND $3 AND e.status<>'cancelled' GROUP BY c.dre_group ORDER BY grupo`,[u.id,start,end]);const income=await pool.query(`SELECT COALESCE(sum(amount_cents),0)::text revenue FROM sales WHERE unit_id=$1 AND sale_date BETWEEN $2 AND $3 AND status='confirmed'`,[u.id,start,end]);const lines=[`competencia;${month}`,`receita_bruta_centavos;${income.rows[0].revenue}`,'grupo;valor_centavos;lancamentos',...r.rows.map(x=>`${x.grupo};${x.valor_centavos};${x.lancamentos}`)];res.setHeader('Content-Type','text/csv; charset=utf-8');res.setHeader('Content-Disposition','attachment; filename="dre.csv"');res.send('\ufeff'+lines.join('\r\n'));}catch(e){next(e);}});
const reportDefinitions={
  sales:{title:'Faturamento',columns:['data','canal','valor_centavos','meta_centavos','status','observacoes'],sql:`SELECT sale_date::text data,channel canal,amount_cents::text valor_centavos,COALESCE(target_cents,0)::text meta_centavos,status,COALESCE(notes,'') observacoes FROM sales WHERE unit_id=$1`,date:'sale_date',search:['channel','notes'],status:['draft','confirmed','void']},
  expenses:{title:'Despesas por competência',columns:['fornecedor','documento','competencia','vencimento','descricao','valor_centavos','status','categoria'],sql:`SELECT e.supplier fornecedor,COALESCE(e.document_number,'') documento,e.accrual_date::text competencia,COALESCE(e.due_date::text,'') vencimento,e.description descricao,e.total_cents::text valor_centavos,e.status,COALESCE(c.name,'Sem categoria') categoria FROM expenses e LEFT JOIN categories c ON c.id=e.category_id WHERE e.unit_id=$1`,date:'e.accrual_date',search:['e.supplier','e.description','e.document_number','c.name'],status:['open','paid','cancelled','review']},
  cash:{title:'Movimentos de caixa',columns:['data','turno','tipo','categoria','descricao','responsavel','valor_centavos','forma_pagamento'],sql:`SELECT m.occurred_at::text data,COALESCE(s.shift_name,'') turno,m.movement_type tipo,m.category categoria,m.description descricao,COALESCE(m.responsible,'') responsavel,m.amount_cents::text valor_centavos,COALESCE(m.payment_method,'') forma_pagamento FROM cash_movements m LEFT JOIN cash_sessions s ON s.id=m.session_id WHERE m.unit_id=$1`,date:'m.occurred_at::date',search:['m.category','m.description','m.responsible','s.shift_name','m.payment_method'],status:['opening','inflow','outflow','reversal']},
  cash_closings:{title:'Fechamentos de caixa',columns:['turno','aberto_em','aberto_por','fechado_em','fechado_por','esperado_centavos','contado_centavos','diferenca_centavos','justificativa'],sql:`SELECT s.shift_name turno,s.opened_at::text aberto_em,COALESCE(op.name,'') aberto_por,s.closed_at::text fechado_em,COALESCE(cl.name,'') fechado_por,COALESCE(s.expected_cents,0)::text esperado_centavos,COALESCE(s.counted_cents,0)::text contado_centavos,COALESCE(s.difference_cents,0)::text diferenca_centavos,COALESCE(s.close_reason,'') justificativa FROM cash_sessions s LEFT JOIN users op ON op.id=s.opened_by LEFT JOIN users cl ON cl.id=s.closed_by WHERE s.unit_id=$1 AND s.closed_at IS NOT NULL`,date:'s.closed_at::date',search:['s.shift_name','op.name','cl.name','s.close_reason']},
  stock:{title:'Posição de estoque por lote',columns:['produto','sku','unidade','minimo','lote','fornecedor','recebido','validade','saldo','custo_unitario_centavos','documento'],sql:`SELECT p.name produto,COALESCE(p.sku,'') sku,p.base_unit unidade,p.minimum_quantity::text minimo,COALESCE(l.lot_code,'') lote,COALESCE(l.supplier,'') fornecedor,COALESCE(l.received_on::text,'') recebido,COALESCE(l.expires_on::text,'') validade,COALESCE(l.quantity_remaining,0)::text saldo,COALESCE(l.unit_cost_cents,0)::text custo_unitario_centavos,COALESCE(l.source_document,'') documento FROM products p LEFT JOIN stock_lots l ON l.product_id=p.id AND l.unit_id=p.unit_id WHERE p.unit_id=$1 AND p.active`,date:'l.received_on',search:['p.name','p.sku','l.lot_code','l.supplier','l.source_document']},
  stock_moves:{title:'Movimentações de estoque',columns:['data','produto','lote','tipo','quantidade','motivo','referencia','responsavel'],sql:`SELECT m.created_at::text data,p.name produto,COALESCE(l.lot_code,'') lote,m.movement_type tipo,m.quantity::text quantidade,COALESCE(m.reason,'') motivo,COALESCE(m.reference,'') referencia,u.name responsavel FROM stock_movements m JOIN products p ON p.id=m.product_id LEFT JOIN stock_lots l ON l.id=m.lot_id LEFT JOIN users u ON u.id=m.created_by WHERE m.unit_id=$1`,date:'m.created_at::date',search:['p.name','l.lot_code','m.movement_type','m.reason','m.reference','u.name'],status:['inbound','outbound','adjustment','waste','courtesy','consumption','reversal']},
  dre:{title:'DRE gerencial · lançamentos de origem',columns:['data','origem','descricao','grupo','valor_centavos','status'],sql:`SELECT * FROM (SELECT sale_date data,'Faturamento' origem,channel descricao,'receita_bruta' grupo,amount_cents::text valor_centavos,status FROM sales WHERE unit_id=$1 AND status='confirmed' UNION ALL SELECT e.accrual_date data,'Despesa' origem,e.description descricao,COALESCE(c.dre_group,'unclassified') grupo,e.total_cents::text valor_centavos,e.status FROM expenses e LEFT JOIN categories c ON c.id=e.category_id WHERE e.unit_id=$1 AND e.status<>'cancelled') report WHERE true`,date:'data',search:['origem','descricao','grupo'],status:['confirmed','open','paid','review']}
};
function reportFilters(input={}){return {from:validDate(input.from)?input.from:null,to:validDate(input.to)?input.to:null,search:text(input.search,120)||'',status:text(input.status,30)||''};}
function reportSql(type,unitId,filters){const def=reportDefinitions[type];if(!def)return null;const values=[unitId],where=[];if(filters.from){values.push(filters.from);where.push(`${def.date}>=$${values.length}`);}if(filters.to){values.push(filters.to);where.push(`${def.date}<=$${values.length}`);}if(filters.status&&def.status?.includes(filters.status)){values.push(filters.status);where.push(`${['cash','stock_moves'].includes(type)?'m.movement_type':'status'}=$${values.length}`);}if(filters.search&&def.search?.length){values.push(`%${filters.search.replace(/[\\%_]/g,'\\$&')}%`);where.push(`(${def.search.map(x=>`${x} ILIKE $${values.length} ESCAPE '\\'`).join(' OR ')})`);}const order=type==='stock'?'produto,validade NULLS LAST,lote':type==='expenses'?'competencia DESC':type==='cash_closings'?'fechado_em DESC':'data DESC';return {def,values,sql:`${def.sql}${where.length?` AND ${where.join(' AND ')}`:''} ORDER BY ${order} LIMIT 5000`};}
function reportCsv(columns,rows){const cell=v=>`"${String(v??'').replace(/"/g,'""')}"`;return '\ufeff'+[columns.join(';'),...rows.map(row=>columns.map(c=>cell(row[c])).join(';'))].join('\r\n');}
app.get('/api/reports/run',async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const type=text(req.query.type,20),filters=reportFilters(req.query),query=reportSql(type,u.id,filters);if(!query)return fail(res,400,'Tipo de relatório inválido.');if(filters.from&&filters.to&&filters.from>filters.to)return fail(res,400,'A data inicial deve ser anterior ou igual à data final.');if(['expenses','cash','cash_closings','dre'].includes(type)&&!['admin','owner','finance','auditor'].includes(req.session.user.role))return fail(res,403,'Seu perfil não pode consultar este relatório.');const r=await pool.query(query.sql,query.values);res.json({type,title:query.def.title,columns:query.def.columns,filters,rows:r.rows,limited:r.rowCount===5000});}catch(e){next(e);}});
app.get('/api/reports/run.csv',async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const type=text(req.query.type,20),filters=reportFilters(req.query),query=reportSql(type,u.id,filters);if(!query)return fail(res,400,'Tipo de relatório inválido.');if(filters.from&&filters.to&&filters.from>filters.to)return fail(res,400,'A data inicial deve ser anterior ou igual à data final.');if(['expenses','cash','cash_closings','dre'].includes(type)&&!['admin','owner','finance','auditor'].includes(req.session.user.role))return fail(res,403,'Seu perfil não pode exportar este relatório.');const r=await pool.query(query.sql,query.values);res.setHeader('Content-Type','text/csv; charset=utf-8');res.setHeader('Content-Disposition',`attachment; filename="${type}-villa-cruz.csv"`);res.send(reportCsv(query.def.columns,r.rows));}catch(e){next(e);}});
app.get('/api/reports/saved',async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const r=await pool.query('SELECT * FROM saved_reports WHERE unit_id=$1 AND (owner_id=$2 OR $3=true) ORDER BY name',[u.id,req.session.user.id,req.session.user.role==='admin']);res.json(r.rows);}catch(e){next(e);}});
app.post('/api/reports/saved',allow('admin','owner','finance','operations'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const name=text(req.body.name,100),type=['sales','expenses','cash','cash_closings','dre','stock','stock_moves'].includes(req.body.report_type)?req.body.report_type:null;if(!name||!type)return fail(res,400,'Informe nome e tipo de relatório.');const row={id:id(),unit_id:u.id,owner_id:req.session.user.id,name,report_type:type,filters:req.body.filters&&typeof req.body.filters==='object'?req.body.filters:{}};await pool.query('INSERT INTO saved_reports(id,unit_id,owner_id,name,report_type,filters) VALUES($1,$2,$3,$4,$5,$6)',Object.values(row));await audit(pool,req,u.id,'create','saved_report',row.id,null,row);res.status(201).json(row);}catch(e){next(e);}});

app.get('/api/audit',allow('admin','owner','auditor'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const r=await pool.query(`SELECT a.id,a.action,a.entity_type,a.entity_id,a.reason,a.before_data,a.after_data,a.created_at,u.name user_name FROM audit_log a LEFT JOIN users u ON u.id=a.user_id WHERE a.unit_id=$1 ORDER BY a.created_at DESC LIMIT 300`,[u.id]);res.json(r.rows);}catch(e){next(e);}});
app.get('/api/products/audit',allow('admin','owner','auditor'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const r=await pool.query(`SELECT p.id,p.name,p.sku,p.created_at,p.updated_at,creator.name created_by_name,last_change.user_name updated_by_name,last_change.created_at changed_at,last_change.before_data,last_change.after_data FROM products p LEFT JOIN users creator ON creator.id=p.created_by LEFT JOIN LATERAL(SELECT a.created_at,a.before_data,a.after_data,actor.name user_name FROM audit_log a LEFT JOIN users actor ON actor.id=a.user_id WHERE a.unit_id=p.unit_id AND a.entity_type='product' AND a.entity_id=p.id AND a.action='update' ORDER BY a.created_at DESC LIMIT 1) last_change ON true WHERE p.unit_id=$1 ORDER BY COALESCE(last_change.created_at,p.created_at) DESC LIMIT 300`,[u.id]);res.json(r.rows);}catch(e){next(e);}});
app.get('/api/admin/users',allow('admin'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const r=await pool.query(`SELECT u.id,u.name,u.email,u.role,u.active,u.must_change_password,u.created_at FROM users u JOIN user_units uu ON uu.user_id=u.id WHERE uu.unit_id=$1 ORDER BY u.name`,[u.id]);res.json(r.rows);}catch(e){next(e);}});
app.post('/api/admin/users',allow('admin'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const d=req.body;const email=text(d.email,254).toLowerCase(),name=text(d.name,120),role=roles.includes(d.role)?d.role:null,password=String(d.password||'');if(!email.includes('@')||!name||!role||password.length<8||Buffer.byteLength(password,'utf8')>72)return fail(res,400,'Informe nome, e-mail, perfil e senha temporária com pelo menos 8 caracteres e até 72 bytes em UTF-8.');const hash=await bcrypt.hash(password,12);const user={id:id(),name,email,hash,role};await inTx(async c=>{await c.query('INSERT INTO users(id,name,email,password_hash,role,must_change_password) VALUES($1,$2,$3,$4,$5,true)',Object.values(user));await c.query('INSERT INTO user_units(user_id,unit_id) VALUES($1,$2)',[user.id,u.id]);await audit(c,req,u.id,'create','user',user.id,null,{name,email,role,must_change_password:true});});res.status(201).json({id:user.id,name,email,role,must_change_password:true});}catch(e){if(e.code==='23505')return fail(res,409,'Já existe usuário com este e-mail.');next(e);}});

app.get('/api/settings',async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const r=await pool.query(`SELECT setting_key,setting_value,effective_from FROM app_settings WHERE unit_id=$1 ORDER BY effective_from DESC`,[u.id]);const result={};for(const row of r.rows)if(!(row.setting_key in result))result[row.setting_key]={value:row.setting_value,effective_from:row.effective_from};res.json(result);}catch(e){next(e);}});
app.post('/api/settings',allow('admin','owner'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const target=parseMoney(req.body.purchase_target_percent);if(target===null||target<0||target>10000)return fail(res,400,'A meta percentual deve estar entre 0% e 100%.');const effective=validDate(req.body.effective_from)?req.body.effective_from:localToday();const setting={id:id(),unit_id:u.id,setting_key:'purchase_target_percent',setting_value:JSON.stringify(target/100),effective_from:effective,created_by:req.session.user.id};await pool.query(`INSERT INTO app_settings(id,unit_id,setting_key,setting_value,effective_from,created_by) VALUES($1,$2,$3,$4::jsonb,$5,$6) ON CONFLICT(unit_id,setting_key,effective_from) DO UPDATE SET setting_value=EXCLUDED.setting_value,created_by=EXCLUDED.created_by`,Object.values(setting));await audit(pool,req,u.id,'update','setting',setting.id,null,{purchase_target_percent:target/100,effective_from:effective});res.json({purchase_target_percent:target/100,effective_from:effective});}catch(e){next(e);}});
const supplierFormFieldVisibilityKeys=['legal_name','trade_name','business_status','main_activity','activity_code','legal_nature','company_size','share_capital','registered_on','email','phone','reference_contact_name','reference_contact_role','reference_contact_phone','reference_contact_email','postal_code','state','street','number','complement','district','city','notes'];
app.post('/api/settings/supplier-form-fields',allow('admin','owner'),async(req,res,next)=>{
  try{
    const u=await routeUnit(req,res);if(!u)return;
    const fields=req.body?.fields;
    if(!fields||typeof fields!=='object'||Array.isArray(fields)||Object.keys(fields).length!==supplierFormFieldVisibilityKeys.length||Object.keys(fields).some(key=>!supplierFormFieldVisibilityKeys.includes(key))||supplierFormFieldVisibilityKeys.some(key=>typeof fields[key]!=='boolean'))return fail(res,400,'Envie a configuração completa dos campos do fornecedor.');
    const effective=localToday();let settingId=id(),before=null;
    await inTx(async c=>{
      const existing=await c.query('SELECT id,setting_value FROM app_settings WHERE unit_id=$1 AND setting_key=$2 AND effective_from=$3',[u.id,'supplier_form_fields',effective]);
      if(existing.rowCount){settingId=existing.rows[0].id;before=existing.rows[0].setting_value;}
      await c.query(`INSERT INTO app_settings(id,unit_id,setting_key,setting_value,effective_from,created_by) VALUES($1,$2,'supplier_form_fields',$3::jsonb,$4,$5) ON CONFLICT(unit_id,setting_key,effective_from) DO UPDATE SET setting_value=EXCLUDED.setting_value,created_by=EXCLUDED.created_by`,[settingId,u.id,JSON.stringify(fields),effective,req.session.user.id]);
      await audit(c,req,u.id,'update','setting',settingId,before,{supplier_form_fields:fields,effective_from:effective});
    });
    res.json({supplier_form_fields:fields,effective_from:effective});
  }catch(e){next(e);}
});
app.post('/api/settings/login-logo',allow('admin','owner'),receiveLoginLogo,async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;if(!req.file)return fail(res,400,'Escolha uma imagem para a logo.');const mimeType=detectLoginLogoType(req.file.buffer),extension=loginLogoTypes[mimeType];if(!mimeType)return fail(res,415,'Envie uma imagem PNG, JPG ou WEBP válida.');const directory=brandingDir(),previous=await readLoginLogo(),fileName=`login-logo-${id()}.${extension}`,filePath=path.join(directory,fileName),metadataPath=path.join(directory,'login-logo.json'),tempMetadataPath=path.join(directory,`login-logo-${id()}.tmp`);await fs.mkdir(directory,{recursive:true});await fs.writeFile(filePath,req.file.buffer,{flag:'wx'});await fs.writeFile(tempMetadataPath,JSON.stringify({file_name:fileName,mime_type:mimeType}),{flag:'wx'});await fs.rename(tempMetadataPath,metadataPath);await audit(pool,req,u.id,'update','branding','login-logo',previous?{mime_type:previous.mime_type}:null,{mime_type:mimeType,size_bytes:req.file.size});if(previous)await fs.unlink(previous.file_path).catch(()=>{});res.json({ok:true,mime_type:mimeType});}catch(e){next(e);}});
app.delete('/api/settings/login-logo',allow('admin','owner'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const previous=await readLoginLogo();await fs.unlink(path.join(brandingDir(),'login-logo.json')).catch(e=>{if(e.code!=='ENOENT')throw e;});if(previous)await fs.unlink(previous.file_path).catch(()=>{});if(previous)await audit(pool,req,u.id,'delete','branding','login-logo',{mime_type:previous.mime_type},null);res.json({ok:true,custom:false});}catch(e){next(e);}});

app.post('/api/import/preview',allow('admin','owner','finance'),upload.single('file'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;if(!req.file)return fail(res,400,'Escolha uma planilha XLSX.');if(!req.file.originalname.toLowerCase().endsWith('.xlsx'))return fail(res,400,'Somente arquivos .xlsx são aceitos nesta versão.');const kind=['sales','expenses','products'].includes(req.body.import_type)?req.body.import_type:null;if(!kind)return fail(res,400,'Escolha o tipo de importação.');const wb=new ExcelJS.Workbook();await wb.xlsx.load(req.file.buffer);const sheetName=text(req.body.sheet_name||wb.worksheets[0]?.name,120);const sheet=wb.getWorksheet(sheetName);if(!sheet)return fail(res,400,'A aba escolhida não existe.');if(sheet.rowCount>10001)return fail(res,413,'A aba excede o limite de 10.000 linhas.');const headers=sheet.getRow(1).values.slice(1).map((_,i)=>text(sheet.getRow(1).getCell(i+1).text,200));const mappedHeaders=headers.map((h,i)=>h||`Coluna ${i+1}`);const rows=[];for(let n=2;n<=sheet.rowCount;n++){const row={};let hasData=false;for(let i=0;i<mappedHeaders.length;i++){const value=sheet.getRow(n).getCell(i+1).text;row[mappedHeaders[i]]=value===''?null:value;if(value!=='')hasData=true;}if(hasData)rows.push(row);}if(!mappedHeaders.length||!rows.length)return fail(res,400,'A aba precisa ter cabeçalho e linhas de dados para pré-visualizar.');const batch={id:id(),unit_id:u.id,user_id:req.session.user.id,source_name:path.basename(req.file.originalname).slice(0,200),sheet_name:sheetName,import_type:kind,headers:JSON.stringify(mappedHeaders),rows_data:JSON.stringify(rows)};await pool.query(`INSERT INTO import_batches(id,unit_id,user_id,source_name,sheet_name,import_type,headers,rows_data) VALUES($1,$2,$3,$4,$5,$6,$7::jsonb,$8::jsonb)`,Object.values(batch));await audit(pool,req,u.id,'preview','import_batch',batch.id,null,{source_name:batch.source_name,sheet:sheetName,kind,rows:rows.length});res.status(201).json({id:batch.id,source_name:batch.source_name,sheet:sheetName,kind,headers:mappedHeaders,rows:rows.slice(0,15),total_rows:rows.length});}catch(e){if(e instanceof multer.MulterError)return fail(res,413,'Arquivo muito grande.');next(e);}});
app.post('/api/import/:id/commit',allow('admin','owner','finance'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const result=await inTx(async c=>{const b=await c.query('SELECT * FROM import_batches WHERE id=$1 AND unit_id=$2 AND user_id=$3 AND status=$4 FOR UPDATE',[req.params.id,u.id,req.session.user.id,'draft']);if(!b.rowCount)return {error:'Rascunho de importação não encontrado ou já processado.'};const mapping=req.body.mapping||{};const rows=b.rows[0].rows_data;let imported=0;const rejected=[];for(let i=0;i<rows.length;i++){const src=rows[i];const get=k=>src[mapping[k]];await c.query('SAVEPOINT import_row');try{if(b.rows[0].import_type==='sales'){const amount=parseMoney(get('amount')),date=normalizeDate(get('sale_date'));if(amount===null||!date)throw Error('data ou valor inválido');await c.query('INSERT INTO sales(id,unit_id,sale_date,channel,amount_cents,target_cents,notes,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8)',[id(),u.id,date,text(get('channel')||'Importado',80),amount,parseMoney(get('target')),text(get('notes'),1000),req.session.user.id]);}
        else if(b.rows[0].import_type==='expenses'){const amount=parseMoney(get('total')),issue=normalizeDate(get('issue_date')),due=normalizeDate(get('due_date')),supplier=text(get('supplier'),160),description=text(get('description')||supplier,250);if(amount===null||!issue||!supplier)throw Error('fornecedor, data ou valor inválido');await c.query('INSERT INTO expenses(id,unit_id,supplier,document_number,issue_date,accrual_date,description,total_cents,due_date,status,created_by) VALUES($1,$2,$3,$4,$5,$5,$6,$7,$8,\'open\',$9)',[id(),u.id,supplier,text(get('document_number'),100)||null,issue,description,amount,due,req.session.user.id]);}
        else {const name=text(get('name'),160),sku=text(get('sku'),80)||null;if(!name)throw Error('nome do produto ausente');await c.query('INSERT INTO products(id,unit_id,name,sku,base_unit,created_by) VALUES($1,$2,$3,$4,$5,$6)',[id(),u.id,name,sku,text(get('unit')||'unidade',30),req.session.user.id]);}
        imported++;await c.query('RELEASE SAVEPOINT import_row');
      }catch(err){await c.query('ROLLBACK TO SAVEPOINT import_row');await c.query('RELEASE SAVEPOINT import_row');rejected.push({line:i+2,message:text(err.message,200)});}}
      const status=imported===rows.length?'completed':imported?'partial':'partial';const report={total:rows.length,imported,rejected};await c.query('UPDATE import_batches SET status=$1,report=$2::jsonb,completed_at=now() WHERE id=$3',[status,JSON.stringify(report),req.params.id]);await audit(c,req,u.id,'commit','import_batch',req.params.id,null,report);return report;});if(result.error)return fail(res,404,result.error);res.json(result);}catch(e){next(e);}});

app.post('/api/attachments',allow('admin','owner','finance','operations'),upload.single('file'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;if(!req.file)return fail(res,400,'Escolha um arquivo.');const type=text(req.body.entity_type,20),entity=text(req.body.entity_id,100);if(!['expense','cash','sale'].includes(type)||!entity)return fail(res,400,'Informe o lançamento relacionado.');if(type==='expense'&&!['admin','owner','finance'].includes(req.session.user.role))return fail(res,403,'Seu perfil não pode acessar anexos de despesas.');const allowed=type==='expense'?['application/pdf','image/jpeg','image/png']:['application/pdf','image/jpeg','image/png'];if(!allowed.includes(req.file.mimetype))return fail(res,415,'Formato não aceito. Envie PDF, JPG ou PNG.');const b=req.file.buffer;const signature=req.file.mimetype==='application/pdf'?b.subarray(0,5).toString()==='%PDF-':req.file.mimetype==='image/png'?b.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])):b[0]===0xff&&b[1]===0xd8&&b[2]===0xff;if(!signature)return fail(res,415,'O conteúdo do arquivo não corresponde ao formato declarado.');const table={expense:'expenses',cash:'cash_movements',sale:'sales'}[type];const valid=await pool.query(`SELECT id FROM ${table} WHERE id=$1 AND unit_id=$2`,[entity,u.id]);if(!valid.rowCount)return fail(res,404,'Registro relacionado não encontrado.');const dir=path.resolve(process.env.UPLOAD_DIR||path.join(__dirname,'data','uploads'));await fs.mkdir(dir,{recursive:true});const stored=id();await fs.writeFile(path.join(dir,stored),b,{flag:'wx'});const row={id:stored,unit_id:u.id,entity_type:type,entity_id:entity,original_name:path.basename(req.file.originalname).slice(0,200),stored_name:stored,mime_type:req.file.mimetype,size_bytes:req.file.size,created_by:req.session.user.id};await inTx(async c=>{await c.query('INSERT INTO attachments(id,unit_id,entity_type,entity_id,original_name,stored_name,mime_type,size_bytes,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)',Object.values(row));await audit(c,req,u.id,'upload','attachment',row.id,null,{entity_type:type,entity_id:entity,name:row.original_name,size_bytes:row.size_bytes});});res.status(201).json({id:row.id,name:row.original_name,mime_type:row.mime_type,size_bytes:row.size_bytes});}catch(e){if(e instanceof multer.MulterError)return fail(res,413,'Arquivo excede o limite permitido.');next(e);}});
app.get('/api/attachments/:id',async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const r=await pool.query('SELECT * FROM attachments WHERE id=$1 AND unit_id=$2',[req.params.id,u.id]);if(!r.rowCount)return fail(res,404,'Anexo não encontrado.');const row=r.rows[0];if(row.entity_type==='expense'&&!['admin','owner','finance','auditor'].includes(req.session.user.role))return fail(res,403,'Seu perfil não pode acessar este anexo.');const dir=path.resolve(process.env.UPLOAD_DIR||path.join(__dirname,'data','uploads'));const file=path.join(dir,row.stored_name);res.setHeader('Content-Type',row.mime_type);res.setHeader('Content-Disposition',`inline; filename*=UTF-8''${encodeURIComponent(row.original_name)}`);res.setHeader('X-Content-Type-Options','nosniff');await audit(pool,req,u.id,'download','attachment',row.id,null,{name:row.original_name});res.sendFile(file);}catch(e){next(e);}});

